// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.messagingimport android.content.Intentimport android.net.Uriimport com.roshan.persona.connectivity.model.MessagingApp/** * NOUS — Messaging Intent Builder (Module 11 v3 — Step 11.2). * * Builds Android [Intent]s for opening chats in different messaging apps * (WhatsApp, Telegram, Signal, SMS) with a pre-filled message. * * ## How it works (per strategy v3 §"Full-Spectrum Messaging Unification") * * ``` * User: "Message Mom on WhatsApp that I'm late" *   ↓ * MessagingIntentBuilder.buildWhatsAppIntent("+919876543210", "I'm late") *   → Intent(ACTION_SENDTO, Uri.parse("https://wa.me/919876543210?text=I'm+late")) *   ↓ * OutboundExecutor opens the intent → WhatsApp chat opens with pre-filled message *   ↓ * MessagingAccessibilityBridge clicks the "Send" button → message sent * ``` * * ## Why Intent.ACTION_SENDTO (not WhatsApp API)? * * WhatsApp/Telegram don't expose public APIs for sending messages from * third-party apps. The only way to automate outbound messages is: * *  1. Open the chat with a pre-filled message (via Intent). *  2. Use AccessibilityService to click the "Send" button. * * This is the same approach used by Tasker + MacroDroid for WhatsApp * automation — it's the industry standard for Android. * * ## Testability * * All methods are pure functions — they build Intent objects without * launching them. The [OutboundExecutor] launches the intent. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§Full-Spectrum Messaging Unification</a> */object MessagingIntentBuilder {    /**     * Build an intent to open a WhatsApp chat with a pre-filled message.     *     * Uses `https://wa.me/<phone>?text=<message>` URL scheme.     * If WhatsApp is installed, it opens the chat directly.     *     * @param phoneNumber the recipient's phone number (with country code, no +).     * @param message the pre-filled message text.     * @return the Intent, or null if phoneNumber is invalid.     */    fun buildWhatsAppIntent(phoneNumber: String, message: String): Intent? {        val normalized = normalizePhoneForWhatsApp(phoneNumber) ?: return null        val encodedMessage = Uri.encode(message)        val uri = Uri.parse("https://wa.me/$normalized?text=$encodedMessage")        return Intent(Intent.ACTION_VIEW, uri).apply {            setPackage("com.whatsapp")            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)        }    }    /**     * Build an intent to open a Telegram chat with a pre-filled message.     *     * Uses `tg://msg?to=<phone>&text=<message>` URL scheme.     *     * @param phoneNumber the recipient's phone number (with country code, no +).     * @param message the pre-filled message text.     * @return the Intent, or null if phoneNumber is invalid.     */    fun buildTelegramIntent(phoneNumber: String, message: String): Intent? {        val normalized = normalizePhoneForWhatsApp(phoneNumber) ?: return null        val encodedMessage = Uri.encode(message)        val uri = Uri.parse("https://t.me/share/url?url=&text=$encodedMessage")        return Intent(Intent.ACTION_VIEW, uri).apply {            setPackage("org.telegram.messenger")            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)        }    }    /**     * Build an intent to open a Signal chat.     *     * Uses Signal's SMS/MMS intent scheme.     *     * @param phoneNumber the recipient's phone number.     * @param message the pre-filled message text.     * @return the Intent, or null if phoneNumber is invalid.     */    fun buildSignalIntent(phoneNumber: String, message: String): Intent? {        val normalized = phoneNumber.filter { it.isDigit() }        if (normalized.isBlank()) return null        return Intent(Intent.ACTION_SENDTO, Uri.parse("smsto:$normalized")).apply {            setPackage("org.thoughtcrime.securesms")            putExtra("sms_body", message)            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)        }    }    /**     * Build an intent to open the SMS app with a pre-filled message.     *     * @param phoneNumber the recipient's phone number.     * @param message the pre-filled message text.     * @return the Intent.     */    fun buildSmsIntent(phoneNumber: String, message: String): Intent {        val normalized = phoneNumber.filter { it.isDigit() }        return Intent(Intent.ACTION_SENDTO, Uri.parse("smsto:$normalized")).apply {            putExtra("sms_body", message)            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)        }    }    /**     * Build the appropriate intent for [app] + [phoneNumber] + [message].     *     * @param app the messaging app to use.     * @param phoneNumber the recipient's phone number.     * @param message the pre-filled message.     * @return the Intent, or null if the app is not supported / phone invalid.     */    fun buildIntent(app: MessagingApp, phoneNumber: String, message: String): Intent? {        return when (app) {            MessagingApp.WHATSAPP -> buildWhatsAppIntent(phoneNumber, message)            MessagingApp.TELEGRAM -> buildTelegramIntent(phoneNumber, message)            MessagingApp.SIGNAL -> buildSignalIntent(phoneNumber, message)            MessagingApp.SMS -> buildSmsIntent(phoneNumber, message)        }    }    /**     * Normalize a phone number for WhatsApp's wa.me URL.     *     * WhatsApp requires: country code + number, no +, no spaces, no dashes.     * Example: "+91 98765 43210" → "919876543210"     *     * @return normalized number, or null if no digits found.     */    internal fun normalizePhoneForWhatsApp(phone: String): String? {        val digits = phone.filter { it.isDigit() }        return if (digits.length >= 7) digits else null    }}